mapper.select:
select od.link_sys_id , sum(smd.menu_price * od.qty + coalesce(opt_sum.option_price, 0)) as total_price from order_detail od left join store_menu_detail smd on smd.sys_id = od.link_sys_id2 left join ( select odo.link_sys_id, sum(smod.menu_option_price * odo.qty) as option_price from order_detail_option odo left join store_menu_option_detail smod on smod.sys_id = odo.link_sys_id2 group by odo.link_sys_id ) opt_sum on opt_sum.link_sys_id = od.sys_id where 1=1 and od.link_sys_id in
#{id}
group by od.link_sys_id

select odo.link_sys_id , sum(smod.menu_option_price * odo.qty) as total_price from order_detail_option odo left join store_menu_option_detail smod on smod.sys_id = odo.link_sys_id2 where 1=1 and odo.link_sys_id in
#{id}
group by odo.link_sys_id
